5	type NodeDef = {label: string; mono?: boolean};
6	type Props = {headline: string; data: {nodes: NodeDef[]; branch: string[]; optional: string; interrupt: string; caption: string}; theme: Record<string, any>};
7	type Th = Record<string, any>;
8	
9	const ease = Easing.bezier(0.16, 1, 0.3, 1);
10	const ramp = (f: number, start: number, dur: number) =>
11	  interpolate(f, [start, start + dur], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease});
12	const clamp01 = (v: number) => Math.max(0, Math.min(1, v));
13	
14	const Chevron = (p: {x: number; y: number; dir: string; theme: Th; o: number}) => {
15	  const d = p.dir === 'd' ? `M${p.x - 9},${p.y - 11} L${p.x},${p.y} L${p.x + 9},${p.y - 11}` : `M${p.x - 11},${p.y - 9} L${p.x},${p.y} L${p.x - 11},${p.y + 9}`;
16	  return <path d={d} fill='none' stroke={p.theme.accent} strokeWidth={3} strokeLinecap='round' strokeLinejoin='round' opacity={p.o} />;
17	};
18	
19	const Box = (p: {x: number; y: number; w: number; h: number; label: string; t: number; active: number; theme: Th; fs: number; mono?: boolean; dashed?: boolean; split?: boolean}) => {
20	  const cut = p.label.indexOf(' ');
21	  const lines = p.split && cut > 0 ? [p.label.slice(0, cut), p.label.slice(cut + 1)] : [p.label];
22	  const dash = p.dashed ? '8 8' : undefined;
23	  return (
24	    <g opacity={p.t} transform={`translate(0 ${(1 - p.t) * 20})`}>
25	      <rect x={p.x} y={p.y} width={p.w} height={p.h} rx={14} fill={p.theme.background} stroke={p.theme.muted} strokeWidth={2} strokeDasharray={dash} />
26	      <rect x={p.x} y={p.y} width={p.w} height={p.h} rx={14} fill='none' stroke={p.theme.accent} strokeWidth={3} strokeDasharray={dash} opacity={p.active} />
27	      {lines.map((l, i) => (
28	        <text key={i} x={p.x + p.w / 2} y={p.y + p.h / 2 + (i - (lines.length - 1) / 2) * (p.fs + 6) + p.fs * 0.35} textAnchor='middle' fontSize={p.fs} fill={p.theme.text} fontFamily={p.mono ? 'monospace' : p.theme.font_body}>{l}</text>
29	      ))}
30	    </g>
31	  );
32	};
