22	      <div style={{width: 320 * line, height: 4, background: theme.accent, borderRadius: theme.radius, marginBottom: 36}} />
23	      <h1 style={{margin: 0, display: 'flex', fontFamily: theme.font_heading, fontWeight: theme.heading_weight, fontSize: size(168, theme), letterSpacing: '-0.02em', lineHeight: 1, color: theme.text}}>
24	        {letters.map((ch, i) => {
