  const theme = props.theme;
  const d = props.data;
  const fade = Math.min(ramp(frame, 0, 6), 1 - ramp(frame, durationInFrames - 10, 10));
  const N = d.nodes.length;
  const W = 1680, NW = 280, NH = 110, GAP = (W - N * NW) / (N - 1), RY = 120, CY = RY + NH / 2;
  const cx = (i: number) => i * (NW + GAP) + NW / 2;
  const D0 = 30, SPAN = 220;
  const tAt = (x: number) => D0 + (SPAN * (x - cx(0))) / (cx(N - 1) - cx(0));
  const dotX = interpolate(frame, [D0, D0 + SPAN], [cx(0), cx(N - 1)], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});
  const nodeT = (i: number) => (i === 0 ? ramp(frame, 6, 20) : ramp(frame, tAt(cx(i) - NW / 2) - 22, 20));
  const nodeA = (i: number) => clamp01((dotX - (cx(i) - NW / 2)) / 30);
  const dotO = ramp(frame, D0 - 8, 8);
  const pulse = 0.5 + 0.5 * Math.sin(frame / 8);
  const bx = cx(2), LY = 330, LH = 100;
  const stem = ramp(frame, tAt(bx), 24);
  const arc = ramp(frame, 270, 34);
  return (
    <AbsoluteFill style={{background: theme.background, color: theme.text, fontFamily: theme.font_body, padding: '90px 120px', opacity: fade}}>
      <div style={{display: 'flex', alignItems: 'center', gap: 40}}>
        <h1 style={{margin: 0, color: theme.text, fontFamily: theme.font_heading, fontWeight: theme.heading_weight, fontSize: size(64, theme), letterSpacing: '-0.02em', ...enterStyle(progress(frame, fps, theme, 0), theme)}}>{props.headline}</h1>
        <div style={{padding: '6px 20px', border: `2px dashed ${theme.body}`, borderRadius: theme.radius, color: theme.body, fontFamily: d.mono, fontSize: size(28, theme), ...enterStyle(progress(frame, fps, theme, 2), theme)}}>{d.tag}</div>
      </div>
      <div style={{flex: 1, display: 'flex', alignItems: 'center'}}>
        <svg width={W} height={500} viewBox={`0 0 ${W} 500`}>
          <path d={`M${cx(0)},${RY} V50 H${cx(N - 1)} V${RY - 6}`} pathLength={1} strokeDasharray={1} strokeDashoffset={1 - arc} fill='none' stroke={theme.muted} strokeWidth={2} />
          <Chevron x={cx(N - 1)} y={RY - 4} dir='d' theme={theme} o={arc >= 1 ? 1 : 0} color={theme.accent} />
          <text x={W / 2} y={60} textAnchor='middle' fontSize={size(30, theme)} fill={theme.body} stroke={theme.background} strokeWidth={28} paintOrder='stroke' opacity={ramp(frame, 292, 20)}>{d.interrupt}</text>
          {d.nodes.map((n, i) => (
            <Box key={i} x={cx(i) - NW / 2} y={RY} w={NW} h={NH} label={n} t={nodeT(i)} active={nodeA(i)} theme={theme} fs={size(32, theme)} />
          ))}
          {d.nodes.slice(0, -1).map((n, i) => {
            const x1 = cx(i) + NW / 2, x2 = cx(i + 1) - NW / 2;
            const fr = clamp01((dotX - x1) / (x2 - x1));
            return (
              <g key={i}>
                <line x1={x1} y1={CY} x2={x2} y2={CY} stroke={theme.muted} strokeWidth={2} opacity={0.4 * nodeT(i + 1)} />
                <line x1={x1} y1={CY} x2={x1 + (x2 - x1) * fr} y2={CY} stroke={theme.accent} strokeWidth={3} />
                <Chevron x={x2} y={CY} dir='r' theme={theme} o={fr >= 1 ? 1 : 0} color={theme.accent} />
              </g>
            );
          })}
          <circle cx={dotX} cy={CY} r={22 + 4 * pulse} fill={theme.accent} opacity={0.22 * dotO} />
          <circle cx={dotX} cy={CY} r={9} fill={theme.accent} opacity={dotO} />
          <line x1={bx} y1={RY + NH} x2={bx} y2={RY + NH + (LY - RY - NH) * stem} stroke={theme.accent} strokeWidth={3} />
          <Box x={bx - 190} y={LY} w={380} h={LH} label={d.branch} t={ramp(frame, tAt(bx) + 18, 22)} active={stem >= 1 ? 1 : 0} theme={theme} fs={size(32, theme)} />
          <text x={W} y={470} textAnchor='end' fontSize={size(30, theme)} fill={theme.muted} opacity={ramp(frame, 322, 24)}>{d.caption}</text>
        </svg>
      </div>
    </AbsoluteFill>
  );
}

import React from 'react';
import {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';
import {enterStyle, progress, size} from './jarvis-kit';

type Th = Record<string, any>;
type CardData = {title: string; sub: string; items: string[]};
type Props = {headline: string; data: {tag: string; badges: string[]; surface: CardData; brain: CardData; mono: string}; theme: Th};

const ease = Easing.bezier(0.16, 1, 0.3, 1);
const ramp = (f: number, start: number, dur: number) =>
  interpolate(f, [start, start + dur], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease});

const Card = (p: {card: CardData; t0: number; frame: number; theme: Th}) => {
  const t = ramp(p.frame, p.t0, 22);
  return (
    <div style={{position: 'relative', width: 600, height: 420, boxSizing: 'border-box', padding: 44, border: `2px solid ${p.theme.muted}`, borderRadius: p.theme.radius, background: p.theme.surface, opacity: t, transform: `translateY(${(1 - t) * 24}px)`}}>
      <div style={{fontFamily: p.theme.font_heading, fontWeight: p.theme.heading_weight, fontSize: size(60, p.theme), letterSpacing: '-0.02em'}}>{p.card.title}</div>
      <div style={{color: p.theme.accent, fontSize: size(36, p.theme), marginTop: 6, marginBottom: 30}}>{p.card.sub}</div>
      {p.card.items.map((it, i) => {
        const q = ramp(p.frame, p.t0 + 16 + i * 8, 18);
        return (
          <div key={i} style={{display: 'flex', alignItems: 'center', gap: 20, marginTop: 18, fontSize: size(38, p.theme), color: p.theme.body, opacity: q, transform: `translateX(${(1 - q) * -16}px)`}}>
            <span style={{width: 18, height: 3, background: p.theme.accent}} />
            {it}
          </div>
        );
      })}
    </div>
  );
};

export default function Scene(props: Props) {
  const frame = useCurrentFrame();
  const {fps, durationInFrames} = useVideoConfig();
  const theme = props.theme;
  const d = props.data;
  const fade = Math.min(ramp(frame, 0, 6), 1 - ramp(frame, durationInFrames - 10, 10));
  const a1 = ramp(frame, 90, 28), a2 = ramp(frame, 118, 28);
  const phase = Math.max(0, frame - 150) % 120 / 120;
  const local = (phase * 2) % 1;
  const dotO = frame < 150 ? 0 : Math.sin(Math.PI * local);
  const dotX = phase < 0.5 ? 30 + 420 * local : 450 - 420 * local;
  const dotY = phase < 0.5 ? 150 : 270;
  return (
    <AbsoluteFill style={{background: theme.background, color: theme.text, fontFamily: theme.font_body, padding: '90px 120px', opacity: fade}}>
      <h1 style={{margin: 0, color: theme.text, fontFamily: theme.font_heading, fontWeight: theme.heading_weight, fontSize: size(64, theme), letterSpacing: '-0.02em', ...enterStyle(progress(frame, fps, theme, 0), theme)}}>{props.headline}</h1>
      <div style={{display: 'flex', alignItems: 'center', gap: 20, marginTop: 28}}>
        <div style={{padding: '6px 20px', border: `2px solid ${theme.accent}`, borderRadius: theme.radius, fontFamily: d.mono, fontSize: size(30, theme), color: theme.text, ...enterStyle(progress(frame, fps, theme, 1), theme)}}>{d.tag}</div>
        {d.badges.map((b, i) => (
          <div key={i} style={{padding: '6px 22px', border: `2px dashed ${theme.muted}`, borderRadius: 999, fontSize: size(30, theme), color: theme.body, opacity: ramp(frame, 14 + i * 8, 18)}}>{b}</div>
        ))}
      </div>
      <div style={{flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center'}}>
        <Card card={d.surface} t0={20} frame={frame} theme={theme} />
        <svg width={480} height={420} viewBox='0 0 480 420'>
          <line x1={30} y1={150} x2={30 + 420 * a1} y2={150} stroke={theme.accent} strokeWidth={3} />
          <path d='M439,139 L450,150 L439,161' fill='none' stroke={theme.accent} strokeWidth={3} strokeLinecap='round' strokeLinejoin='round' opacity={a1 >= 1 ? 1 : 0} />
          <line x1={450} y1={270} x2={450 - 420 * a2} y2={270} stroke={theme.accent} strokeWidth={3} />
          <path d='M41,259 L30,270 L41,281' fill='none' stroke={theme.accent} strokeWidth={3} strokeLinecap='round' strokeLinejoin='round' opacity={a2 >= 1 ? 1 : 0} />
          <circle cx={dotX} cy={dotY} r={20} fill={theme.accent} opacity={0.22 * dotO} />
          <circle cx={dotX} cy={dotY} r={8} fill={theme.accent} opacity={dotO} />
        </svg>
        <Card card={d.brain} t0={50} frame={frame} theme={theme} />
      </div>
    </AbsoluteFill>
  );
}

import React from 'react';
import {AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig} from 'remotion';
import {enterStyle, progress, size} from './jarvis-kit';

type Th = Record<string, any>;
type Props = {headline: string; data: {rows: string[]; commands: string[]; prereq: string; closing: string; note: string; mono: string}; theme: Th};

const ease = Easing.bezier(0.16, 1, 0.3, 1);
const ramp = (f: number, start: number, dur: number) =>
  interpolate(f, [start, start + dur], [0, 1], {extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease});

const Lock = (p: {c: number; theme: Th}) => (
  <svg width={64} height={84} viewBox='0 0 64 84'>
    <path d='M18,42 V30 a14,14 0 0 1 28,0 V42' transform={`translate(0 ${-14 * (1 - p.c)})`} fill='none' stroke={p.c > 0.5 ? p.theme.accent : p.theme.muted} strokeWidth={4} strokeLinecap='round' />
    <rect x={8} y={42} width={48} height={34} rx={6} fill='none' stroke={p.theme.text} strokeWidth={3} />
    <circle cx={32} cy={59} r={4.5} fill={p.theme.accent} opacity={p.c} />
  </svg>
);

export default function Scene(props: Props) {
  const frame = useCurrentFrame();
  const {fps, durationInFrames} = useVideoConfig();
  const theme = props.theme;
  const d = props.data;
  const fade = Math.min(ramp(frame, 0, 6), 1 - ramp(frame, durationInFrames - 15, 15));
  const starts = [30, 80];
  const counts = d.commands.map((c, i) => Math.max(0, Math.min(c.length, Math.floor((frame - starts[i]) * 0.5))));
  const typing = counts[1] > 0 ? 1 : 0;
  const blink = frame % 30 < 18 ? 1 : 0;
  const dim = 1 - 0.65 * ramp(frame, 150, 20);
  const close = ramp(frame, 150, 24);
  return (
    <AbsoluteFill style={{background: theme.background, color: theme.text, fontFamily: theme.font_body, padding: '90px 120px', opacity: fade}}>
      <h1 style={{margin: 0, color: theme.text, fontFamily: theme.font_heading, fontWeight: theme.heading_weight, fontSize: size(64, theme), letterSpacing: '-0.02em', ...enterStyle(progress(frame, fps, theme, 0), theme)}}>{props.headline}</h1>
      <div style={{flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center', gap: 64}}>
        <div style={{display: 'flex', gap: 60, alignItems: 'center', opacity: dim}}>
          <div style={{width: 780, display: 'flex', flexDirection: 'column', gap: 28}}>
            {d.rows.map((r, i) => {
              const t = ramp(frame, 10 + i * 14, 20);
              const c = ramp(frame, 30 + i * 14, 14);
              return (
                <div key={i} style={{display: 'flex', alignItems: 'center', gap: 32, padding: '20px 32px', border: `2px solid ${theme.muted}`, borderRadius: theme.radius, background: theme.surface, fontSize: size(38, theme), opacity: t, transform: `translateX(${(1 - t) * -28}px)`}}>
                  <Lock c={c} theme={theme} />
                  {r}
                </div>
              );
            })}
          </div>
          <div style={{width: 780, boxSizing: 'border-box', border: `2px solid ${theme.muted}`, borderRadius: theme.radius, background: theme.surface, overflow: 'hidden', opacity: ramp(frame, 20, 22), transform: `translateY(${(1 - ramp(frame, 20, 22)) * 24}px)`}}>
            <div style={{display: 'flex', gap: 10, padding: '16px 22px', borderBottom: `2px solid ${theme.muted}`}}>
              {[0, 1, 2].map((k) => <span key={k} style={{width: 14, height: 14, borderRadius: 7, background: theme.muted, opacity: 0.6}} />)}
            </div>
            <div style={{padding: '36px 36px 36px', fontFamily: d.mono, fontSize: size(30, theme), lineHeight: 1.9}}>
              {d.commands.map((c, i) => (
                <div key={i} style={{display: 'flex', alignItems: 'center', minHeight: 57, opacity: frame >= starts[i] - 4 ? 1 : 0}}>
                  <span style={{color: theme.accent, marginRight: 18}}>$</span>
                  <span style={{color: theme.text}}>{c.slice(0, counts[i])}</span>
                  {typing === i ? <span style={{display: 'inline-block', width: 14, height: 30, marginLeft: 4, background: theme.accent, opacity: counts[i] >= c.length ? blink : 1}} /> : null}
                </div>
              ))}
              <div style={{marginTop: 12, color: theme.muted, fontFamily: theme.font_body, fontSize: size(30, theme), opacity: ramp(frame, 122, 20)}}>{d.prereq}</div>
            </div>
          </div>
        </div>
        <div style={{opacity: close, transform: `translateY(${(1 - close) * 20}px)`}}>
          <div style={{width: 160 * close, height: 4, background: theme.accent, borderRadius: theme.radius, marginBottom: 20}} />
          <div style={{color: theme.accent, fontFamily: theme.font_heading, fontWeight: theme.heading_weight, fontSize: size(72, theme), letterSpacing: '-0.02em'}}>{d.closing}</div>
          <div style={{display: 'inline-block', marginTop: 14, paddingTop: 16, borderTop: `2px dashed ${theme.muted}`, color: theme.text, fontSize: size(44, theme)}}>{d.note}</div>
        </div>
      </div>
    </AbsoluteFill>
  );
}
